import {state,esc,totalProgress} from '../../lib/store.js';
import {fields} from '../../data/seed.js';
import {CHAPTER_STATUSES,literatureReferences} from '../../lib/research/model.js';
import {panel,bar,button,badge,input,area,select,tabs,empty} from '../pixel/primitives.js';
import {taskList} from '../hud/home.js';
import {library} from '../library/library.js';

const opt=(value,label,current='')=>`<option value="${esc(value)}" ${String(value)===String(current)?'selected':''}>${esc(label)}</option>`;
const linkedChapter=id=>state.chapters.find(chapter=>String(chapter.id)===String(id));
const linkedTheory=id=>state.theories.find(theory=>String(theory.id)===String(id));
const selectLink=(name,label,records,current,format)=>`<label class="field"><span>${label}</span><select name="${name}">${opt('','未关联',current)}${records.map(record=>opt(record.id,format(record),current)).join('')}</select></label>`;
const preview=(value,fallback='尚未填写。')=>`<p class="research-preview">${esc(value||fallback)}</p>`;

function thesisView(){
 const chapters=state.chapters||[],cards=chapters.map((chapter,index)=>`<article class="chapter research-card" data-chapter-id="${esc(chapter.id)}"><div class="row chapter-title"><div><span class="chapter-number">${esc(chapter.number)}</span><h3>${esc(chapter.title)}</h3></div><div class="chapter-progress"><b>${chapter.progress}%</b>${badge(chapter.status,'magenta')}</div></div>${bar(chapter.progress,chapter.title,'magenta')}<input type="range" min="0" max="100" step="1" value="${chapter.progress}" data-change="chapter" data-id="${esc(chapter.id)}" aria-label="${esc(chapter.title)}进度"><div class="chapter-summary"><span>SUMMARY / 章节概述</span>${preview(chapter.summary,'No summary yet.')}${String(chapter.summary||'').length>180?`<details><summary>VIEW FULL SUMMARY</summary><p class="research-preview full-preview">${esc(chapter.summary)}</p></details>`:''}</div><div class="actions">${button('EDIT','chapter-edit',`data-id="${esc(chapter.id)}"`)}${button('MOVE UP','chapter-move',`data-id="${esc(chapter.id)}" data-value="up" ${index===0?'disabled':''}`,'small')}${button('MOVE DOWN','chapter-move',`data-id="${esc(chapter.id)}" data-value="down" ${index===chapters.length-1?'disabled':''}`,'small')}${button('DELETE','chapter-delete',`data-id="${esc(chapter.id)}"`,'danger small')}</div></article>`).join('');
 const thesis=panel('THESIS STRUCTURE',`<form data-form="thesis" class="thesis-settings">${input('title','THESIS TITLE / 论文题目',state.thesisTitle,'text','maxlength="160" placeholder="可选"')}<div class="row wrap">${input('deadline','DEADLINE / 截止日期',state.deadline,'date')}<button class="button">SAVE SETTINGS</button></div></form><div class="overall-progress"><div class="row"><span class="micro muted">THESIS OVERALL PROGRESS</span><b class="big-number">${totalProgress()}%</b></div>${bar(totalProgress(),'论文总进度','magenta')}</div><div class="row wrap research-section-head"><div><h3>THESIS STRUCTURE</h3><p>Build your thesis structure chapter by chapter.<br>按自己的论文结构添加章节。</p></div>${button('＋ ADD CHAPTER / 新增章节','chapter-add','','primary')}</div>${cards||empty('NO CHAPTERS YET / 尚未创建论文章节。')}`,'','research-thesis');
 return `<div class="grid research-thesis-grid"><div class="stack">${thesis}</div>${panel('RESEARCH QUESTS',taskList(true))}</div>`;
}

function theoryView(){
 const cards=state.theories.map(theory=>{const chapter=linkedChapter(theory.chapterId);return `<article class="research-card theory-card"><div class="row wrap">${badge('THEORY','magenta')}<span class="micro muted">${esc(theory.scholar)}${theory.year?' · '+esc(theory.year):''}</span></div><h3>${esc(theory.theory||'Untitled Theory')}</h3>${preview(theory.coreConcepts,'No core concepts yet.')}<div class="research-links"><span>CHAPTER → ${esc(chapter?`${chapter.number} / ${chapter.title}`:'未关联')}</span><span>RQ → ${esc(theory.researchQuestion||'未关联')}</span></div><div class="tag-list">${String(theory.tags||'').split(',').map(tag=>tag.trim()).filter(Boolean).map(tag=>badge(tag)).join('')}</div><div class="actions">${button('VIEW','theory-view',`data-id="${esc(theory.id)}"`)}${button('EDIT','theory-edit',`data-id="${esc(theory.id)}"`)}${button('DELETE','theory-delete',`data-id="${esc(theory.id)}"`,'danger')}</div></article>`}).join('');
 return `<div class="row wrap research-intro"><div><h2>THEORY FRAMEWORK / 理论框架</h2><p>Build a local, profile-scoped map of concepts and scholars.</p></div>${button('＋ ADD THEORY / 新增理论','theory-add','','primary')}</div><div class="research-card-grid">${cards||empty('NO THEORY NOTES YET / 尚无理论笔记')}</div>`;
}

function literatureView(ui){
 const query=String(ui.paperSearch||'').toLowerCase(),papers=state.papers.filter(paper=>{const haystack=[paper.title,paper.author,paper.tags,paper.keywords].join(' ').toLowerCase();return (!query||haystack.includes(query))&&(!ui.paperTopic||paper.topic===ui.paperTopic)&&(!ui.paperYear||String(paper.year)===String(ui.paperYear))&&(!ui.paperStatus||paper.status===ui.paperStatus)&&(!ui.paperType||paper.type===ui.paperType)});
 const values=key=>[...new Set(state.papers.map(paper=>paper[key]).filter(Boolean).map(String))].sort();
 const filters=`<form class="searchbar research-search" data-form="paper-search"><input name="q" value="${esc(ui.paperSearch)}" placeholder="Search title, author, tags, keywords…" aria-label="搜索文献"><select name="topic" aria-label="主题筛选">${opt('','ALL TOPICS',ui.paperTopic)}${values('topic').map(value=>opt(value,value,ui.paperTopic)).join('')}</select><select name="year" aria-label="年份筛选">${opt('','ALL YEARS',ui.paperYear)}${values('year').map(value=>opt(value,value,ui.paperYear)).join('')}</select><select name="status" aria-label="阅读状态筛选">${opt('','ALL STATUS',ui.paperStatus)}${values('status').map(value=>opt(value,value,ui.paperStatus)).join('')}</select><select name="type" aria-label="类型筛选">${opt('','ALL TYPES',ui.paperType)}${values('type').map(value=>opt(value,value,ui.paperType)).join('')}</select><button class="button">FILTER</button></form>`;
 const cards=papers.map(paper=>{const chapter=linkedChapter(paper.chapterId),theory=linkedTheory(paper.theoryId);return `<article class="paper research-card"><div class="row wrap">${badge(paper.topic||'未分类','magenta')}${badge(paper.status||'待读')}</div><h3>${esc(paper.title)}</h3><p class="meta">${esc(paper.author||'Unknown author')} / ${esc(paper.year||'—')} / ${esc(paper.type||'—')}</p><div class="small muted">${esc(paper.tags||paper.keywords||'No tags')}</div>${bar(paper.progress,'阅读进度')}<p class="micro muted">THEORY → ${esc(theory?.theory||paper.theory||'未关联')}<br>CHAPTER → ${esc(chapter?`${chapter.number} / ${chapter.title}`:paper.chapter||'未关联')}<br>RQ → ${esc(paper.researchQuestion||paper.rq||paper.question||'未关联')}</p><div class="actions">${button('EDIT LITERATURE','paper-edit',`data-id="${esc(paper.id)}"`)}${paper.fileId?button('OPEN LOCAL FILE','file-open',`data-id="${esc(paper.fileId)}"`):''}</div></article>`}).join('');
 return `<div class="row wrap research-intro"><div><h2>DATABASE / 文献</h2><p>Individual literature database. One source equals one local record.</p></div>${button('＋ ADD LITERATURE','paper-edit','','primary')}</div>${filters}<div class="research-card-grid">${cards||empty(query||ui.paperTopic||ui.paperYear||ui.paperStatus||ui.paperType?'NO MATCHING LITERATURE':'NO LITERATURE YET / 尚无文献记录')}</div>`;
}

function reviewView(){
 const cards=state.reviewThemes.map(theme=>{const literature=theme.literatureIds.map(literatureId=>state.papers.find(paper=>String(paper.id)===String(literatureId))).filter(Boolean);return `<article class="research-card review-theme-card"><div class="row wrap">${badge('REVIEW THEME','magenta')}<span class="micro muted">${literature.length} LITERATURE</span></div><h3>${esc(theme.title)}</h3>${preview(theme.description,'No description yet.')}<p class="micro cyan">RQ → ${esc(theme.researchQuestion||'未关联')}</p><div class="linked-literature">${literature.map(paper=>`<span>${esc(paper.title)} · ${esc(paper.author||'')}</span>`).join('')||'<span>NO LINKED LITERATURE</span>'}</div><div class="actions">${button('VIEW','review-view',`data-id="${esc(theme.id)}"`)}${button('EDIT','review-edit',`data-id="${esc(theme.id)}"`)}${button('DELETE','review-delete',`data-id="${esc(theme.id)}"`,'danger')}</div></article>`}).join('');
 return `<div class="row wrap research-intro"><div><h2>LITERATURE REVIEW / 文献综述</h2><p>Organize and compare your literature by research theme.<br>按研究主题整理、比较并形成文献综述。</p></div>${button('＋ NEW REVIEW THEME / 新增综述主题','review-add','','primary')}</div><div class="research-card-grid">${cards||empty('NO REVIEW THEMES YET / 尚无综述主题')}</div>`;
}

export function research(ui){let body='';if(ui.research==='overview')body=thesisView();if(ui.research==='theory')body=theoryView();if(ui.research==='papers')body=literatureView(ui);if(ui.research==='review')body=reviewView();if(ui.research==='library')body=library(ui);return `<div class="research-lab">${tabs([['overview','THESIS / 论文'],['papers','DATABASE / 文献'],['theory','THEORY FRAMEWORK / 理论框架'],['review','LITERATURE REVIEW / 文献综述'],['library','LOCAL LIBRARY / 本地资料']],ui.research,'research')}${body}</div>`}

export function chapterForm(id){const chapter=state.chapters.find(record=>String(record.id)===String(id))||{number:String(state.chapters.length+1).padStart(2,'0'),title:'',summary:'',progress:0,status:'NOT STARTED'};return `<form data-form="chapter" data-id="${esc(chapter.id||'')}"><div class="formgrid">${input('number','CHAPTER NUMBER / 章节编号',chapter.number,'text','required maxlength="24"')}${input('title','TITLE / 章节标题',chapter.title,'text','required maxlength="240"')}${input('progress','PROGRESS / 进度',chapter.progress,'number','required min="0" max="100"')}${select('status','STATUS / 状态',CHAPTER_STATUSES,chapter.status)}${area('summary','SUMMARY / 章节概述',chapter.summary,'class="full" maxlength="100000"')}</div><div class="foot"><button type="button" class="button" data-action="close">CANCEL</button><button class="button primary">SAVE CHAPTER</button></div></form>`}

export function theoryForm(id){const theory=state.theories.find(record=>String(record.id)===String(id))||{};return `<form data-form="theory" data-id="${esc(theory.id||'')}"><div class="formgrid">${input('theory','THEORY / 理论名称',theory.theory,'text','required maxlength="240"')}${input('scholar','SCHOLAR / 学者',theory.scholar,'text','maxlength="180"')}${input('source','SOURCE / 来源',theory.source,'text','maxlength="500"')}${input('year','YEAR / 年份',theory.year,'number','min="0" max="2200"')}${selectLink('chapterId','LINKED CHAPTER / 关联章节',state.chapters,theory.chapterId,chapter=>`${chapter.number} / ${chapter.title}`)}${input('researchQuestion','LINKED RESEARCH QUESTION / 关联研究问题',theory.researchQuestion)}${input('tags','TAGS / 标签',theory.tags)}${area('coreConcepts','CORE CONCEPTS / 核心概念',theory.coreConcepts,'class="full"')}${area('notes','MY NOTES / 我的笔记',theory.notes,'class="full"')}${area('relevance','RELEVANCE / 与研究关系',theory.relevance,'class="full"')}</div><div class="foot"><button type="button" class="button" data-action="close">CANCEL</button><button class="button primary">SAVE THEORY</button></div></form>`}

export function theoryDetail(id){const theory=state.theories.find(record=>String(record.id)===String(id));if(!theory)return empty('THEORY NOT FOUND');const chapter=linkedChapter(theory.chapterId);return `<article class="research-detail"><h3>${esc(theory.theory)}</h3><p class="meta">${esc(theory.scholar)}${theory.year?' · '+esc(theory.year):''}${theory.source?' · '+esc(theory.source):''}</p><h4>CORE CONCEPTS</h4>${preview(theory.coreConcepts)}<h4>MY NOTES</h4>${preview(theory.notes)}<h4>RELEVANCE</h4>${preview(theory.relevance)}<p class="micro muted">CHAPTER → ${esc(chapter?`${chapter.number} / ${chapter.title}`:'未关联')}<br>RQ → ${esc(theory.researchQuestion||'未关联')}<br>TAGS → ${esc(theory.tags||'—')}</p><div class="actions">${button('EDIT','theory-edit',`data-id="${esc(theory.id)}"`)}${button('CLOSE','close')}</div></article>`}

export function paperForm(id){const paper=state.papers.find(record=>String(record.id)===String(id))||{progress:0,type:'Book',status:'待读'};return `<form data-form="paper" data-id="${esc(paper.id||'')}"><div class="formgrid">${input('title','TITLE / 标题',paper.title,'text','required maxlength="240"')}${input('author','AUTHOR / 作者',paper.author)}${input('year','YEAR / 年份',paper.year,'number','min="0" max="2200"')}${select('type','TYPE / 类型',['Book','Article','Essay','Thesis','Note'],paper.type)}${select('status','READING STATUS / 阅读状态',['待读','阅读中','已读'],paper.status)}${input('progress','READING PROGRESS / 阅读进度 %',paper.progress,'number','min="0" max="100" required')}${input('topic','TOPIC / 主题',paper.topic||paper.theme)}${input('tags','TAGS / 标签（逗号分隔）',paper.tags)}${input('keywords','KEYWORDS / 关键词',paper.keywords)}${selectLink('theoryId','LINKED THEORY / 关联理论',state.theories,paper.theoryId,theory=>theory.theory)}${selectLink('chapterId','LINKED CHAPTER / 关联章节',state.chapters,paper.chapterId,chapter=>`${chapter.number} / ${chapter.title}`)}${input('researchQuestion','LINKED RESEARCH QUESTION',paper.researchQuestion||paper.rq||paper.question)}<label class="field"><span>LINKED LOCAL FILE / 关联本地文件</span><select name="fileId">${opt('','无关联',paper.fileId)}${state.files.map(file=>opt(file.id,file.name,paper.fileId)).join('')}</select></label>${Object.entries(fields).filter(([key])=>key!=='question').map(([key,label])=>area(key,label,paper[key],'class="full"')).join('')}</div><div class="foot">${paper.id?button('DELETE LITERATURE','paper-delete',`data-id="${esc(paper.id)}"`,'danger'):''}<button type="button" class="button" data-action="close">CANCEL</button><button class="button primary">SAVE LITERATURE</button></div></form>`}

export function reviewThemeForm(id){const theme=state.reviewThemes.find(record=>String(record.id)===String(id))||{literatureIds:[]},selected=new Set(theme.literatureIds.map(String));return `<form data-form="review-theme" data-id="${esc(theme.id||'')}"><div class="formgrid">${input('title','THEME TITLE / 主题',theme.title,'text','required maxlength="240"')}${input('researchQuestion','RESEARCH QUESTION / 研究问题',theme.researchQuestion)}${area('description','DESCRIPTION / 说明',theme.description,'class="full"')}<fieldset class="field full literature-picker"><legend>LINKED LITERATURE / 关联文献</legend>${state.papers.length?state.papers.map(paper=>`<label><input type="checkbox" name="literatureIds" value="${esc(paper.id)}" ${selected.has(String(paper.id))?'checked':''}><span>${esc(paper.title)} · ${esc(paper.author||'')}</span></label>`).join(''):'<p class="muted">请先在 DATABASE 中创建文献。</p>'}</fieldset>${area('commonPoints','COMMON POINTS / 共同观点',theme.commonPoints,'class="full"')}${area('differences','DIFFERENCES / 不同观点',theme.differences,'class="full"')}${area('methods','METHODS / 研究方法比较',theme.methods,'class="full"')}${area('keyFindings','KEY FINDINGS / 主要发现',theme.keyFindings,'class="full"')}${area('researchGap','RESEARCH GAP / 研究空白',theme.researchGap,'class="full"')}${area('synthesis','MY SYNTHESIS / 我的综合评价',theme.synthesis,'class="full"')}${area('notes','NOTES / 其他笔记',theme.notes,'class="full"')}</div><div class="foot"><button type="button" class="button" data-action="close">CANCEL</button><button class="button primary">SAVE REVIEW THEME</button></div></form>`}

export function reviewThemeDetail(id){const theme=state.reviewThemes.find(record=>String(record.id)===String(id));if(!theme)return empty('REVIEW THEME NOT FOUND');const literature=theme.literatureIds.map(literatureId=>state.papers.find(paper=>String(paper.id)===String(literatureId))).filter(Boolean);const section=(title,value)=>`<section><h4>${title}</h4>${preview(value)}</section>`;return `<article class="research-detail"><h3>${esc(theme.title)}</h3>${preview(theme.description)}<p class="micro cyan">RESEARCH QUESTION → ${esc(theme.researchQuestion||'未关联')}</p><section><h4>LINKED LITERATURE</h4>${literature.map(paper=>`<div class="listrow"><div class="content"><h3>${esc(paper.title)}</h3><p>${esc(paper.author||'')} · ${esc(paper.year||'')}</p></div>${button('EDIT','paper-edit',`data-id="${esc(paper.id)}"`,'small')}</div>`).join('')||'<p class="muted">NO LINKED LITERATURE</p>'}</section>${section('COMMON POINTS',theme.commonPoints)}${section('DIFFERENCES',theme.differences)}${section('METHODS',theme.methods)}${section('KEY FINDINGS',theme.keyFindings)}${section('RESEARCH GAP',theme.researchGap)}${section('MY SYNTHESIS',theme.synthesis)}${section('NOTES',theme.notes)}<div class="actions">${button('EDIT','review-edit',`data-id="${esc(theme.id)}"`)}${button('CLOSE','close')}</div></article>`}

export function literatureReferenceCount(id){return literatureReferences(state,id).length}
